    def sgn(x):
        return -1 if x < 0 else (1 if x > 0 else 0)

    def man(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def cheb(a, b):
        dx = abs(a[0] - b[0])
        dy = abs(a[1] - b[1])
        return dx if dx > dy else dy

    def step(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

